function ServerSideSorting({
  caption = "{{caption}}",
  accent = "{{accent}}",
  direction = "{{direction}}",
  loading = {{loading}},
  latency = {{latency}},
}) {
  const rows = [
    ["#1042", "A. Whitfield", "Shipped", "£22.00"],
    ["#1041", "R. Okafor", "Processing", "£40.00"],
    ["#1040", "M. Iqbal", "Shipped", "£64.00"],
    ["#1039", "S. Novak", "Refunded", "£128.50"],
  ];
  const cell = { padding: "10px 14px", borderBottom: "1px solid #24143020", whiteSpace: "nowrap" };
  return (
    <div style={{ maxWidth: 480, borderRadius: 10, border: "1px solid #24143020", overflow: "hidden", font: "14px system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <div style={{ overflowX: "auto", opacity: loading ? .55 : 1, transition: "opacity .15s" }}>
        <table style={{ borderCollapse: "collapse", width: "100%" }}>
          <caption style={{ textAlign: "left", fontWeight: 600, padding: "10px 14px" }}>
            {caption}{" "}
            <span role="status" style={{ fontWeight: 400, fontSize: 12, color: "#241430a0", marginLeft: 6, display: "inline-flex", alignItems: "center", gap: 6 }}>
              {loading ? <>Sorting&#8230;</> : <>&#183; {latency}ms</>}
            </span>
          </caption>
          <thead>
            <tr style={{ background: accent, color: "#FAF7F2" }}>
              <th scope="col" style={cell}>Order</th>
              <th scope="col" style={cell}>Customer</th>
              <th scope="col" style={cell}>Status</th>
              <th scope="col" style={cell} aria-sort={direction}>
                <button type="button" style={{ background: "none", border: 0, font: "inherit", color: "inherit", cursor: "pointer", display: "inline-flex", gap: 4, alignItems: "center", padding: 0 }}>
                  Total <span aria-hidden="true" style={{ display: "inline-block", transform: direction === "descending" ? "rotate(180deg)" : "none" }}>{direction !== "none" && "▲"}</span>
                </button>
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row[0]}>{row.map((c, j) => <td key={j} style={cell}>{c}</td>)}</tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
